QByteArray deobf(const unsigned char *data, int size, int keyStored) {
    const unsigned char key = static_cast<unsigned char>(keyStored ^ 0xA7);
    QByteArray out(size, Qt::Uninitialized);
    for (int i = 0; i < size; ++i)
        out.data()[i] = static_cast<char>(data[i] ^ key ^ 0x5C);
    return out;
}

